package com.skyclone.mod.mayors;

import com.google.gson.Gson;

import java.io.Reader;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Content tables for every event this module runs ({@code data/mayors/events.json}, generated by
 * {@code tools/gen/mayors/gen_mayors.py}). Pure Java, Gson-shaped.
 */
public final class EventData {

    /** One shop line: pay {@code coins} plus every "ID:amount" in {@code cost}, receive {@code amount} x {@code result}. */
    public static final class Offer {
        public String result;
        public int amount = 1;
        public double coins;
        public List<String> cost = new ArrayList<>();
    }

    /** A loot line: the first id in {@code items} that exists is given (alternatives keep the odds). */
    public static final class Drop {
        public List<String> items = new ArrayList<>();
        public double chance;
    }

    public static final class Lot {
        public String item;
        public double minBid;
        public int weight = 1;
    }

    public static final class DarkAuction {
        public double entryPurse = 400_000;
        public int rounds = 5;
        public int darkerRounds = 7;
        public int previewSeconds = 5;
        public int bidSeconds = 10;
        public int lobbySeconds = 60;
        public List<Lot> lots = new ArrayList<>();
        public List<Lot> bookRound = new ArrayList<>();
        public List<Lot> darkerLots = new ArrayList<>();
        public List<Lot> darkerFinal = new ArrayList<>();
    }

    public static final class Zoo {
        public List<String> legendaryRotation = new ArrayList<>();
        public List<Offer> offers = new ArrayList<>();
    }

    public static final class Bracket {
        public String id;
        public String name;
        /** Rank-based bracket (top N) when &gt; 0. */
        public int rank;
        public long minPoints;
        public double coins;
        public List<String> items = new ArrayList<>();
        public int sbxp;
    }

    public static final class CandyBoosts {
        public Map<String, Double> armorSets = new HashMap<>();
        public Map<String, Double> accessories = new HashMap<>();
        public double petBat;
    }

    public static final class PartyChest {
        public double chance = 0.005;
        public int[] green = {3, 8};
        public int[] purple = {0, 2};
        public int[] coins = {1000, 5000};
    }

    public static final class Spooky {
        public double baseCandyChance = 0.10;
        public double purpleShare = 0.10;
        public int greenPoints = 1;
        public int purplePoints = 5;
        public double trickOrTreatChance = 0.01;
        public double trickOrTreatSpookyChance = 0.03;
        public List<Offer> shop = new ArrayList<>();
        public List<Bracket> brackets = new ArrayList<>();
        public CandyBoosts candyBoosts = new CandyBoosts();
        public PartyChest partyChest = new PartyChest();
    }

    /** Gift / box / burrow treasure: coins range, optional skill XP and north stars, plus a drop table. */
    public static final class Bag {
        public int[] coins = {0, 0};
        public int[] skillXp = {0, 0};
        public int[] northStars = {0, 0};
        public List<Drop> drops = new ArrayList<>();
    }

    public static final class Myth {
        public int chainLength = 4;
        public double mobChance = 0.35;
        public int radiusMin = 18;
        public int radiusMax = 55;
        public Map<String, Map<String, Integer>> pools = new HashMap<>();
        public Map<String, Bag> treasure = new HashMap<>();
        public List<Offer> shop = new ArrayList<>();
        /** Burrows per chain by the spade you dig with (wave 5); {@code chainLength} is the fallback. */
        public Map<String, Integer> chainBySpade = new HashMap<>();
        /** Extra burrows when the spade carries the Erudite reforge, and the cap. */
        public int eruditeBonus = 2;
        public int chainMax = 10;
    }

    public static final class NewYear {
        public List<Offer> shop = new ArrayList<>();
    }

    public static final class Siege {
        public int rounds = 5;
        public int breakSeconds = 90;
        public int roundSeconds = 240;
        public List<Map<String, Integer>> waves = new ArrayList<>();
        public double hpPerRound = 0.5;
        public int northStarsPerRound = 1;
        public int redTop = 1;
        public double greenShare = 0.25;
        public int stolenForNoRed = 3;
    }

    public static final class Winter {
        public List<Offer> einary = new ArrayList<>();
        public List<Offer> sherry = new ArrayList<>();
        public Siege siege = new Siege();
    }

    public static final class Stonks {
        public double minBid = 2_000_000;
        public double coinsPerStock = 2_000_000;
        public List<Offer> shop = new ArrayList<>();
    }

    /** One line of the carnival token shop. */
    public static final class TokenOffer {
        public String result;
        public int amount = 1;
        public long tokens;
    }

    /** One of Scorekeeper Odette's goals: reach {@code target} of {@code kind} in {@code game} (FRUIT / FISH / SHOOT). */
    public static final class Goal {
        public String id;
        public String game;
        /** plays (counted across games) or a single-game stat: score, apples, unique, dragonfruit, caught, yellow, streak, kills, diamond, lamps. */
        public String kind;
        public int target;
        public long tokens;
        public int tickets;
        public String text;
    }

    /** A Carnival Perk bought with tokens: tier n costs {@code costs[n-1]}, each tier worth {@code perTier} {@code unit}. */
    public static final class Perk {
        public String id;
        /** The calendar event it helps during (spooky_festival, season_of_jerry, ...). */
        public String event;
        public String name;
        public List<Long> costs = new ArrayList<>();
        public double perTier;
        public String unit = "";
        public String effect;
    }

    /** The Carnival (Fairground perk): daily tickets, the three booths, goals, perks and the token shop. */
    public static final class Carnival {
        public int ticketsPerDay = 25;
        public int gameCost = 5;
        public int digs = 15;
        public double tokensPerPoint = 0.01;
        public int digSeconds = 300;
        public int shootSeconds = 100;
        public int fishSeconds = 100;
        public Map<String, Integer> grid = new LinkedHashMap<>();
        public Map<String, Integer> points = new HashMap<>();
        public List<Goal> goals = new ArrayList<>();
        public List<Perk> perks = new ArrayList<>();
        public List<TokenOffer> shop = new ArrayList<>();

        public Perk perk(String id) {
            for (Perk p : perks) if (p.id.equalsIgnoreCase(id)) return p;
            return null;
        }
    }

    public DarkAuction darkAuction = new DarkAuction();
    public Carnival carnival = new Carnival();
    public Zoo zoo = new Zoo();
    public Spooky spooky = new Spooky();
    public Map<String, Bag> gifts = new HashMap<>();
    public Map<String, Bag> jerryBoxes = new HashMap<>();
    public Myth myth = new Myth();
    public NewYear newYear = new NewYear();
    public Winter winter = new Winter();
    public Stonks stonks = new Stonks();

    /** The best bracket a rank and a point total earn (brackets are listed best first), or null. */
    public static Bracket bracketFor(List<Bracket> brackets, int rank, long points, double scale) {
        for (Bracket b : brackets) {
            if (b.rank > 0 && rank > b.rank) continue;
            if (points >= Math.ceil(b.minPoints * scale)) return b;
        }
        return null;
    }

    public static EventData parse(Reader in) {
        EventData d = new Gson().fromJson(in, EventData.class);
        return d == null ? new EventData() : d;
    }
}
